const rows = [];
const strip = (h) => String(h || '').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<br\s*\/?>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&#8377;|&#x20b9;|&rupee;/gi, '₹').replace(/&amp;/g, '&').replace(/\s+/g, ' ');
for (const it of $input.all()) {
  const j = it.json;
  const raw = (j.text && String(j.text).trim()) ? String(j.text).replace(/\s+/g, ' ') : strip(typeof j.html === 'string' ? j.html : j.textAsHtml);
  const orderId = (raw.match(/order id:?\s*(\d+)/i) || [])[1] || '';
  const start = raw.search(/Order Items/i);
  let seg = start >= 0 ? raw.slice(start + 11) : '';
  const stop = seg.search(/Item Total|Item Bill|Bill Details|Sub Total|Subtotal|Grand Total|Order Total|Payment/i);
  if (stop > 0) seg = seg.slice(0, stop);
  const re = /(\d+) x (.+?) ₹\s?([\d,]+(?:\.\d+)?)/g;
  let m; let n = 0;
  while ((m = re.exec(seg)) !== null) {
    n++;
    rows.push({ json: { date: String(j.date || '').slice(0, 10), orderId, qty: Number(m[1]), item: m[2].trim(), lineTotal: Number(m[3].replace(/,/g, '')) } });
  }
  if (n === 0) rows.push({ json: { date: String(j.date || '').slice(0, 10), orderId, qty: 0, item: 'PARSE_FAILED', lineTotal: 0 } });
}
return rows;
